import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.DXGs2oJ2.js";const u=JSON.parse('{"title":"AI Memory Handbook","description":"A full-lifecycle practice guide for enterprise AI memory systems — 23 chapters across 7 parts. Written and led by Hu Jingkun. Mnemosyne OS.","frontmatter":{"title":"AI Memory Handbook","description":"A full-lifecycle practice guide for enterprise AI memory systems — 23 chapters across 7 parts. Written and led by Hu Jingkun. Mnemosyne OS."},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1793361704000}'),r={name:"en/index.md"};function o(s,e,c,h,l,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-memory-handbook" tabindex="-1">AI Memory Handbook <a class="header-anchor" href="#ai-memory-handbook" aria-label="Permalink to &quot;AI Memory Handbook&quot;">​</a></h1><p><strong>From Context Memory to Cognitive Infrastructure: A Full-Lifecycle Practice Guide for Enterprise AI Memory Systems</strong></p><blockquote><p>Version 2026.11 · Data and facts snapshot as of 30 October 2026 Author: <strong>Hu Jingkun (胡景堃)</strong> · Licensed under CC BY-NC-ND 4.0</p></blockquote><p><a href="/ai-memory-handbook/00-preface/阅读导引">中文版</a> · <a href="/ai-memory-handbook/contents">Full contents (Chinese)</a> · <a href="/ai-memory-handbook/reading-guide">Reading guide (Chinese)</a></p><p>This is the complete English edition — all 23 chapters and 2 appendices, translated in full, not abridged.</p><hr><h2 id="part-i-·-architecture-chapters-1–3" tabindex="-1">Part I · Architecture (Chapters 1–3) <a class="header-anchor" href="#part-i-·-architecture-chapters-1–3" aria-label="Permalink to &quot;Part I · Architecture (Chapters 1–3)&quot;">​</a></h2><p>Memory is not an accessory feature. It is simultaneously the input to context, the state of the runtime, and the evidence of governance — and those three identities have incompatible correctness requirements. Merging them into &quot;a piece of text we stored&quot; is the common root cause of most memory incidents in production.</p><ul><li><a href="/ai-memory-handbook/en/ch01-why-memory-is-first-class">Ch. 1 — Why Memory Became a First-Class Primitive</a> — Four failure modes, the three identities of memory, three fundamental tensions, and the honest boundary of what a memory system can and cannot do in 2026.</li><li><a href="/ai-memory-handbook/en/ch02-reference-architecture">Ch. 2 — A Reference Architecture for Memory Systems</a> — Five responsibility domains with an explicit guarantee strength for each. Confusing best-effort with strong-guarantee is how audit and deletion end up permanently unimplemented.</li><li><a href="/ai-memory-handbook/en/ch03-form-and-maturity">Ch. 3 — Form and Maturity: L1–L4</a> — Graded on responsibility and verifiability rather than autonomy. Each level jump has a different cost character: discipline, then verification, then organization.</li></ul><h2 id="part-ii-·-build-chapters-4–7" tabindex="-1">Part II · Build (Chapters 4–7) <a class="header-anchor" href="#part-ii-·-build-chapters-4–7" aria-label="Permalink to &quot;Part II · Build (Chapters 4–7)&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/ch04-writing">Ch. 4 — Writing: Extraction, Typing, Conflict Resolution</a> — Single-pass ADD-only is a choice about the shape of failure, not about speed. Dual time axis, six conflict kinds, four actions.</li><li><a href="/ai-memory-handbook/en/ch05-storage">Ch. 5 — Storage: Tiering, Scoping, Lossless Compression</a> — Isolation correctness guaranteed by structure rather than discipline; hot/warm/cold tiering as reversible demotion; AIC compression that restores byte-for-byte.</li><li><a href="/ai-memory-handbook/en/ch06-retrieval">Ch. 6 — Retrieval: Multi-Signal Fusion and Budget Control</a> — Why pure vector retrieval fails on long-horizon memory, why budget must participate in selection, and how to diagnose ranking versus budget errors.</li><li><a href="/ai-memory-handbook/en/ch07-integration">Ch. 7 — Integration: MCP, API, and Framework Adapters</a> — Designing a 55-entry tool surface (44 native + 11 client-compatible, 3 deprecated aliases, 52 distinct capabilities); degradation must be reported, never silent.</li></ul><h2 id="part-iii-·-run-chapters-8–11" tabindex="-1">Part III · Run (Chapters 8–11) <a class="header-anchor" href="#part-iii-·-run-chapters-8–11" aria-label="Permalink to &quot;Part III · Run (Chapters 8–11)&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/ch08-deployment">Ch. 8 — Deployment: What Local-First Really Means</a> — Zero dependencies as an architectural outcome: four consequences and their costs, four deployment forms, the self-host versus SaaS boundary.</li><li><a href="/ai-memory-handbook/en/ch09-state-and-consistency">Ch. 9 — State Recovery, Asynchrony, and Consistency</a> — Sync versus async writes, the flush barrier as the only way out of read-after-write inconsistency, events, idempotency, and recovery drills.</li><li><a href="/ai-memory-handbook/en/ch10-scoping">Ch. 10 — Scoping for Multi-User and Multi-Agent</a> — Physical isolation turns a cross-tenant leak into a missing file; the namespace derivation trap passes every test and still leaks; cross-agent sharing remains unsolved.</li><li><a href="/ai-memory-handbook/en/ch11-operating-at-scale">Ch. 11 — Operating at Scale: Cost, Latency, Capacity</a> — Four cost structures, why the SQLite ceiling is set by write concurrency rather than data volume, and the metrics that reveal recall degrading over session length.</li></ul><h2 id="part-iv-·-governance-chapters-12–15" tabindex="-1">Part IV · Governance (Chapters 12–15) <a class="header-anchor" href="#part-iv-·-governance-chapters-12–15" aria-label="Permalink to &quot;Part IV · Governance (Chapters 12–15)&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/ch12-auditability">Ch. 12 — Auditability: Hash Chains, Provenance, Evidence</a> — A log is the system&#39;s statement about itself; an audit is material for independent review. The hash chain&#39;s real value is <code>first_broken_at</code>.</li><li><a href="/ai-memory-handbook/en/ch13-deletion-and-forgetting">Ch. 13 — The Four Semantics of Deletion and Forgetting</a> — Mark-delete, mask, cascade soft-delete, physical delete. Deletion verifiability remains unsolved, and this book does not claim otherwise.</li><li><a href="/ai-memory-handbook/en/ch14-pre-write-safety">Ch. 14 — Pre-Write Safety: Notary, Injection, Credentials</a> — Safety must happen before the write. Three classes of attack need three layers of defence; character-level checks cannot stop a forged fact.</li><li><a href="/ai-memory-handbook/en/ch15-compliance">Ch. 15 — Compliance and Data Sovereignty</a> — Self-hosting transfers compliance responsibility rather than eliminating it; the deliverable is an evidence chain, not a feature list.</li></ul><h2 id="part-v-·-optimization-chapters-16–19" tabindex="-1">Part V · Optimization (Chapters 16–19) <a class="header-anchor" href="#part-v-·-optimization-chapters-16–19" aria-label="Permalink to &quot;Part V · Optimization (Chapters 16–19)&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/ch16-benchmarks">Ch. 16 — Benchmarks: A Reproducible Methodology</a> — Three trust tiers, five essentials, three red lines. <strong>This chapter also states explicitly that our own published scores have not yet been independently recomputed by a complete in-repository run.</strong></li><li><a href="/ai-memory-handbook/en/ch17-benchmark-controversy">Ch. 17 — Benchmark Controversy and Evaluation Traps</a> — Five variables each capable of a double-digit gap; why the first selection question is &quot;how many turns&quot;, not &quot;what is your score&quot;; five concrete traps.</li><li><a href="/ai-memory-handbook/en/ch18-quality-and-badcase-loop">Ch. 18 — Quality Measurement and the Badcase Loop</a> — Six quality dimensions in structural conflict; honest metrics return <code>null</code> rather than <code>0</code>; the value of a badcase loop is in attribution, not the fix.</li><li><a href="/ai-memory-handbook/en/ch19-controlled-self-evolution">Ch. 19 — Controlled Self-Evolution: From Storage to Experience</a> — Storage → reflection → experience, each failing differently. Mandatory <code>preconditions</code> is the dividing line between an experience and a suggestion.</li></ul><h2 id="part-vi-·-practice-chapters-20–22" tabindex="-1">Part VI · Practice (Chapters 20–22) <a class="header-anchor" href="#part-vi-·-practice-chapters-20–22" aria-label="Permalink to &quot;Part VI · Practice (Chapters 20–22)&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/ch20-system-comparison">Ch. 20 — Comparing the First Tier</a> — Write paradigms have converged: single-pass ADD-only is now the industry floor and no longer a differentiator. Differentiation lies in conflict adjudication, deletion provability, audit locatability, and cost structure.</li><li><a href="/ai-memory-handbook/en/ch21-selection-and-migration">Ch. 21 — Selection Decisions and Migration Paths</a> — Five prerequisite questions, a decision tree, and three migration paths whose cost tracks architectural position rather than feature gap.</li><li><a href="/ai-memory-handbook/en/ch22-scenarios">Ch. 22 — Representative Scenarios in Practice</a> — Five scenarios, each with one decisive failure mode that is usually not &quot;remembered the wrong thing&quot;, and one scriptable acceptance metric.</li></ul><h2 id="part-vii-·-outlook-chapter-23" tabindex="-1">Part VII · Outlook (Chapter 23) <a class="header-anchor" href="#part-vii-·-outlook-chapter-23" aria-label="Permalink to &quot;Part VII · Outlook (Chapter 23)&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/ch23-unsolved-problems">Ch. 23 — Unsolved Problems and the 2027 Roadmap</a> — Who defines factual correctness, cross-agent arbitration, the verifiability of forgetting, the benchmark gap, and the cost-quality frontier. The bottleneck in each is an incentive structure, not a technique.</li></ul><h2 id="appendices" tabindex="-1">Appendices <a class="header-anchor" href="#appendices" aria-label="Permalink to &quot;Appendices&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/appendix-a-glossary">Appendix A — Glossary</a> — 30 terms with unified renderings, definitions, and the confusable pairs.</li><li><a href="/ai-memory-handbook/en/appendix-b-references">Appendix B — References and Reproducible Resources</a> — Papers with arXiv identifiers, official product documentation, and the exact queries anyone can recompute.</li></ul><h2 id="preface-and-front-matter" tabindex="-1">Preface and front matter <a class="header-anchor" href="#preface-and-front-matter" aria-label="Permalink to &quot;Preface and front matter&quot;">​</a></h2><ul><li><a href="/ai-memory-handbook/en/2026-technical-observations">2026 Technical Observations on Memory Systems</a></li><li><a href="/ai-memory-handbook/en/preface">Preface</a></li><li><a href="/ai-memory-handbook/en/reading-guide">Reading Guide</a></li></ul><h2 id="about-mnemosyne-os" tabindex="-1">About Mnemosyne OS <a class="header-anchor" href="#about-mnemosyne-os" aria-label="Permalink to &quot;About Mnemosyne OS&quot;">​</a></h2><p>This book cites <a href="https://ai-memory.net" target="_blank" rel="noreferrer">Mnemosyne OS</a> extensively, not because it is superior, but because it satisfies two conditions at once: the design documentation matches the implementation source, and the key capabilities can be verified locally. You can <code>pip install mnemosyne-os</code> and reproduce the behaviours described in the book rather than taking the prose on trust.</p><ul><li>Website: <a href="https://ai-memory.net" target="_blank" rel="noreferrer">ai-memory.net</a></li><li>Source: <a href="https://github.com/MnemosyneOS/mnemosyne" target="_blank" rel="noreferrer">github.com/MnemosyneOS/mnemosyne</a></li><li>Reproducible benchmark: <a href="https://github.com/MnemosyneOS/mnemosyne-bench" target="_blank" rel="noreferrer">github.com/MnemosyneOS/mnemosyne-bench</a></li></ul><h2 id="co-building-and-licensing" tabindex="-1">Co-building and licensing <a class="header-anchor" href="#co-building-and-licensing" aria-label="Permalink to &quot;Co-building and licensing&quot;">​</a></h2><p>We welcome universities and educational institutions worldwide to co-build the <em>Enterprise AI Memory</em> curriculum. Add WeChat <strong>Mnemosyne-OS</strong> and mention &quot;co-build&quot;.</p><p><em>AI Memory Handbook</em> was initiated and led by <strong>Hu Jingkun (胡景堃)</strong>. Thanks to the university experts and scholars, AI memory developers, and community volunteers at home and abroad who participated in co-creation.</p><p>Copyright © 2026 Hu Jingkun (胡景堃). Licensed under <a href="https://creativecommons.org/licenses/by-nc-nd/4.0/" target="_blank" rel="noreferrer">CC BY-NC-ND 4.0</a>. <strong>Unauthorized dissemination, reproduction, reprinting, adaptation, or commercial use is prohibited.</strong></p>',32)])])}const p=a(r,[["render",o]]);export{u as __pageData,p as default};
